<?php
namespace App\Http\Controllers;
use App\Models\News; use App\Models\Category; use Illuminate\Http\Request; use Illuminate\Support\Str;
class NewsController extends Controller { public function show(News $news){abort_unless($news->status==='published',404); $news->increment('views'); return view('public.news',compact('news'));} public function create(){return view('submit',['categories'=>Category::where('status','active')->orderBy('name')->get()]);} public function store(Request $request){$data=$request->validate(['title'=>'required|string|max:255','content'=>'required|string','category_id'=>'required|exists:categories,id','image'=>'nullable|image|max:5120']); $data['slug']=Str::slug($data['title']).'-'.Str::lower(Str::random(6)); $data['author_id']=$request->user()->id; $data['author_name']=$request->user()->username; $data['is_anonymous']=$request->boolean('is_anonymous'); $data['status']='pending'; if($request->hasFile('image')) $data['image']=$request->file('image')->store('news','public'); News::create($data); return redirect()->route('dashboard')->with('success','Your news has been submitted for moderation.');} }
